import{_ as e,o as a,c as d,a0 as o}from"./chunks/framework.DzvPB4Y-.js";const m=JSON.parse('{"title":"时间与资源排程（Gantt）：适用问题与学习路线","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/frameworks/gantt/index.md","filePath":"zh-cn/frameworks/gantt/index.md"}'),i={name:"zh-cn/frameworks/gantt/index.md"};function r(l,t,c,n,h,s){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="时间与资源排程-gantt-适用问题与学习路线" tabindex="-1">时间与资源排程（Gantt）：适用问题与学习路线 <a class="header-anchor" href="#时间与资源排程-gantt-适用问题与学习路线" aria-label="Permalink to &quot;时间与资源排程（Gantt）：适用问题与学习路线&quot;">​</a></h1><p>为活动选择执行方式和开始时间，同时安排设备、人员等资源，并满足依赖、工作日历与物料事件。第一课使用有限候选活动 MILP，不需要把活动先变成路径。</p><h2 id="最少需要理解的对象" tabindex="-1">最少需要理解的对象 <a class="header-anchor" href="#最少需要理解的对象" aria-label="Permalink to &quot;最少需要理解的对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务概念</th><th>API</th><th>角色</th><th>核心字段</th></tr></thead><tbody><tr><td>活动</td><td><code>Activity</code></td><td>输入</td><td>业务工作单元；取消需显式声明代价</td></tr><tr><td>执行模式</td><td><code>ActivityMode</code></td><td>输入</td><td>时长、允许起点、费用和资源占用段</td></tr><tr><td>资源</td><td><code>ActivityResource</code></td><td>输入</td><td>容量、不可用区间与分时容量</td></tr><tr><td>依赖</td><td><code>ActivityDependency</code></td><td>输入</td><td>活动端点关系及时间界限</td></tr><tr><td>排程问题</td><td><code>ActivitySchedulingProblem</code></td><td>输入</td><td>活动、资源、依赖、实际执行记录与基准排程</td></tr><tr><td>排程结果</td><td><code>ActivitySchedule</code></td><td>输出</td><td>任务模式与时间、资源占用、取消、费用与实际执行记录</td></tr></tbody></table><p>允许起点定义了业务允许的开始时间，不是搜索次数上限：只给 08:00 和 10:00，就不会允许 09:00 开始。资源占用采用左闭右开区间 <code>[start, end)</code>，即包含开始时刻、不包含结束时刻；起点可用不代表执行全程可用。</p><div class="tip custom-block"><p class="custom-block-title">取消与资源阶段的空值</p><p><code>cancellationCost = null</code> / <code>cancellation_cost = None</code> 表示任务必须执行；0 表示允许免费取消。<code>ActivityResourceUse.until</code> 为空表示占用持续到模式结束，不是零时长。</p></div><h2 id="从哪个入口调用" tabindex="-1">从哪个入口调用？ <a class="header-anchor" href="#从哪个入口调用" aria-label="Permalink to &quot;从哪个入口调用？&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Kotlin 与 Rust 的入口差异</p><p>两种语言都有 <code>ActivitySchedulingApplicationService</code>。独立服务和嵌入联合模型的上下文对象使用相同的领域建模步骤。虽然接口名为 <code>ColumnGenerationSolver</code>，本课只调用它的整数求解能力，不执行列生成。</p></div><p>排产层级的划分不会改变本课活动服务的调用方式。批量任务与列生成排程可在熟悉基本活动模型后继续学习，算法名称见<a href="./../#terminology">术语说明</a>。</p><p>有限起点活动排程无需切换列生成入口。允许起点是业务可选集合，不能当作最大节点数使用；求解时间/节点限制属于具体后端配置。先用少量起点复核日历，再按业务时间粒度扩展，<a href="./business-scenario.html#entry-budget">第二课</a>保留相同服务入口。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>不承诺任意连续时间排程、自动抢占/分批或完整行业法规。</li><li>工作日历不可用区间不会自动转化为“暂停后继续执行”。</li><li>资源容量和物料库存需要分别建模；同一技能组的总人数限制，不能替代“同一名人员不能同时执行两个活动”的约束。</li><li>普通 Gantt 不强制依赖 Network；跨地点行驶子问题才需要评估组合。</li></ul><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>完成<a href="./../setup.html">环境准备</a>。</li><li>跟随<a href="./first-schedule.html">第一次活动排程</a>，检查模式、依赖和资源占用。</li><li>加入停机、基准排程调整与物料事件，区分已实际执行记录和待优化决策。</li><li>阅读<a href="/ospf/zh-cn/guide/rolling-optimization.html">滚动优化</a>，再看<a href="/ospf/zh-cn/examples/framework-example4.html">航班恢复综合案例</a>。</li></ol><h2 id="接口参考" tabindex="-1">接口参考 <a class="header-anchor" href="#接口参考" aria-label="Permalink to &quot;接口参考&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-gantt-scheduling/gantt-scheduling-domain-activity-context/README_ch.md" target="_blank" rel="noreferrer">Kotlin 活动模型与接口</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-gantt-scheduling/src/domain/activity/README_ch.md" target="_blank" rel="noreferrer">Rust 活动模型与接口</a></li></ul><p><a href="./../">返回场景选型</a></p><h2 id="继续实践" tabindex="-1">继续实践 <a class="header-anchor" href="#继续实践" aria-label="Permalink to &quot;继续实践&quot;">​</a></h2><p>下一课：<a href="./first-schedule.html">第一次活动排程</a>。完成后再学<a href="./business-scenario.html">停机日历与滚动重排</a>。将场景迁入自己的应用前，完成<a href="./../integration.html">业务接入检查</a>。</p>',19)])])}const p=e(i,[["render",r]]);export{m as __pageData,p as default};
